def get_0_regions_info(grid):
    h, w = grid.shape
    visited = np.zeros((h, w), dtype=bool)
    regions = []

    for r in range(h):
        for c in range(w):
            if grid[r, c] == 0 and not visited[r, c]:
                stack = [(r, c)]
                region = [(r, c)]
                visited[r, c] = True
                boundary = []

                while stack:
                    curr_r, curr_c = stack.pop()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr, nc] != 0 and (nr, nc) not in boundary:
                                boundary.append((nr, nc))
                            if grid[nr, nc] == 0 and not visited[nr, nc]:
                                visited[nr, nc] = True
                                stack.append((nr, nc))
                regions.append((region, boundary))

    return regions

